var i=`0581-sambusa`;var t=`world-0581`;var o=`TJ`;var a=`central-asia`;var l=8;var r=69;var s={en:`Sambusa`,ua:`Самбуса`};var g={en:`A traditional dish from Tajikistan, centered on all-purpose flour, lamb, yellow onion, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Таджикистан. Основні складники: пшеничне борошно універсальне, ягнятина, жовта цибуля, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,430,`g`],[`water`,195,`ml`],[`table-salt`,6,`g`],[`unsalted-butter`,85,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:9,i:[[`lamb`,400,`g`],[`yellow-onion`,220,`g`],[`ground-cumin`,5,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:16,i:[]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 28 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 28 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:28,i:[[`chicken-egg`,1,`pcs`]]}];var d={slug:i,id:t,country:`TJ`,region:a,servings:8,minutes:69,title:s,text:g,steps:u};export{o as country,d as default,t as id,r as minutes,a as region,l as servings,i as slug,u as steps,g as text,s as title};